window.ATLAS_ITEMS=window.ATLAS_ITEMS||{};window.ATLAS_ITEMS[232]={"id":"232","numero":232,"titre":"Fibrillation atriale","objectifs":[{"id":"232-1","rang":"A","rubrique":"Définition","titre":"Connaître la définition de la fibrillation atriale (FA)","contenu":"<p>La <span class=\"kw-def\">fibrillation atriale</span> est un <strong>trouble du rythme d'origine supraventriculaire</strong>, résultant d'une <span class=\"kw-def\">activité électrique rapide et irrégulière des oreillettes</span>, à une fréquence atriale de <span class=\"kw-chiffre\">400 à 600/min</span>. C'est le <strong>trouble du rythme le plus fréquent</strong>.</p>\n      <ul>\n        <li>La FA peut <strong>faire suite</strong> ou <strong>s'associer</strong> à un <span class=\"kw-def\">flutter atrial</span> typique ou atypique.</li>\n        <li>Il n'y a <span class=\"kw-alerte\">plus de durée minimale de 30 secondes</span> d'enregistrement exigée pour porter le diagnostic de FA.</li>\n        <li>En revanche, le diagnostic par <span class=\"kw-clinique\">photopléthysmographie</span> (montres connectées) reste <span class=\"kw-alerte\">non valide</span> : il impose une confirmation <span class=\"kw-imagerie\">ECG</span>.</li>\n      </ul>\n      <div class=\"callout callout-warn\"><strong>Piège classique.</strong> Sur l'<span class=\"kw-imagerie\">ECG</span>, la FA à <span class=\"kw-radio\">grosses mailles</span> ne doit pas être confondue avec un <span class=\"kw-def\">flutter atrial</span> : le <span class=\"kw-clinique\">flutter</span> a une activité atriale <em>régulière</em> en dents de scie, la FA reste <span class=\"kw-alerte\">totalement irrégulière</span>.</div>\n      <p class=\"obj-renvois\"><em>📎 Items liés : 231 — <span class=\"kw-imagerie\">ECG</span> · 237 — <span class=\"kw-clinique\">Palpitations</span></em></p>","frequence":0},{"id":"232-2","rang":"B","rubrique":"Eléments Physiopathologiques","titre":"Connaître la physiopathologie de la FA","contenu":"<p>La FA naît d'un <span class=\"kw-def\">substrat atrial</span> et de <span class=\"kw-def\">déclencheurs (triggers)</span> électriques, et s'auto-entretient par un remodelage progressif des oreillettes — un véritable <strong>cercle vicieux</strong>.</p>\n      <table >\n        <thead><tr><th>Niveau</th><th>Mécanisme</th></tr></thead>\n        <tbody>\n          <tr>\n            <td><strong>Origine électrophysiologique</strong></td>\n            <td>\n              <strong>Triggers :</strong> activités ectopiques focales au niveau des <span class=\"kw-def\">veines pulmonaires</span> (extrasystoles atriales précoces)<br>\n              <strong>Substrat :</strong> <span class=\"kw-def\">remodelage atrial</span> — <span class=\"kw-def\">dilatation</span> et <span class=\"kw-def\">fibrose</span> atriales facilitant des arythmies par <strong>réentrée</strong>\n            </td>\n          </tr>\n          <tr>\n            <td><strong>Conséquences aux oreillettes</strong></td>\n            <td>\n              Contractions désynchronisées avec <strong>perte de l'efficacité hémodynamique</strong> :<br>\n              <strong>Perte de la systole atriale</strong> ; perte de l'adaptation physiologique de la FC à l'effort<br>\n              <span class=\"kw-alerte\">Risque d'insuffisance cardiaque</span> et <span class=\"kw-alerte\">risque thrombo-embolique</span> par stase dans l'<strong>auricule gauche</strong>\n            </td>\n          </tr>\n          <tr>\n            <td><strong>Conséquences aux ventricules</strong></td>\n            <td>\n              La réponse ventriculaire dépend de la capacité de filtration (période réfractaire) du <span class=\"kw-def\">nœud auriculo-ventriculaire</span>, seule connexion électrique entre étages atrial et ventriculaire :<br>\n              Réponse ventriculaire <strong>irrégulière</strong>, de fréquence variable selon le tonus du système nerveux autonome et les médicaments bradycardisants<br>\n              La <span class=\"kw-clinique\">tachycardie</span> raccourcit le temps de remplissage ventriculaire (↓ VTD donc ↓ VES)\n            </td>\n          </tr>\n          <tr>\n            <td><strong><span class=\"kw-clinique\">Évolution</span></strong></td>\n            <td>\n              <span class=\"kw-def\">Fibrose</span> de l'oreillette puis, plus tardivement, du tissu de conduction (nœud sinusal et nœud AV)<br>\n              <span class=\"kw-def\">Dilatation atriale</span> qui <strong>pérennise la FA</strong> (cercle vicieux auto-entretenu)\n            </td>\n          </tr>\n        </tbody>\n      </table>\n      <p><strong>Complications.</strong> La FA est responsable d'<span class=\"kw-alerte\">1/4 des AVC ischémiques</span> ; elle peut être <strong>cause ou conséquence</strong> d'une <span class=\"kw-ci\">insuffisance cardiaque</span> ; elle favorise les <span class=\"kw-clinique\">troubles cognitifs</span>.</p>\n      <p class=\"obj-renvois\"><em>📎 Items liés : 340 — <span class=\"kw-alerte\">AVC</span> · 234 — <span class=\"kw-ci\">Insuffisance cardiaque</span></em></p>","frequence":0},{"id":"232-3","rang":"B","rubrique":"Prévalence, Epidémiologie","titre":"Connaître l’épidémiologie de la FA","contenu":"<p>La FA est le <strong>trouble du rythme le plus fréquent</strong> : <span class=\"kw-chiffre\">1 individu sur 3</span> présentera une FA au cours de sa vie.</p>\n      <ul>\n        <li><strong><span class=\"kw-def\">Prévalence</span> en France</strong> : entre <span class=\"kw-chiffre\">500 000 et 700 000</span> personnes.</li>\n        <li><span class=\"kw-def\">Prévalence</span> variable selon les pays : rôle de l'<span class=\"kw-etio\">ethnicité</span> et de la <span class=\"kw-etio\">génétique</span>.</li>\n        <li><strong>Âge</strong> : la <span class=\"kw-def\">prévalence</span> <span class=\"kw-alerte\">augmente avec l'âge</span> — rare avant <span class=\"kw-chiffre\">50 ans</span>, mais concerne <span class=\"kw-chiffre\">10 %</span> des sujets de plus de <span class=\"kw-chiffre\">80 ans</span>.</li>\n        <li><strong>Sex-ratio</strong> : prédominance masculine.</li>\n        <li><strong><span class=\"kw-etio\">Obésité</span></strong> : lien fort — la <span class=\"kw-def\">prévalence</span> augmente de <span class=\"kw-chiffre\">5 %</span> pour chaque <span class=\"kw-chiffre\">5 kg/m²</span> supplémentaires.</li>\n      </ul>\n      <div class=\"callout callout-info\"><strong>À retenir.</strong> L'<span class=\"kw-etio\">âge</span> et l'<span class=\"kw-etio\">obésité</span> sont les deux déterminants épidémiologiques majeurs — l'<span class=\"kw-etio\">obésité</span> est un <strong>facteur modifiable</strong>, cible de la correction des <span class=\"kw-def\">facteurs de risque</span>.</div>\n      <p class=\"obj-renvois\"><em>📎 Items liés : 253 — <span class=\"kw-etio\">Obésité</span></em></p>","frequence":0},{"id":"232-4","rang":"A","rubrique":"Diagnostic Positif","titre":"Connaître les symptômes usuels","contenu":"<p>Les signes fonctionnels peuvent être <strong>absents ou intermittents</strong> : la FA est souvent <span class=\"kw-alerte\">asymptomatique</span> et découverte fortuitement sur un <span class=\"kw-imagerie\">ECG</span>.</p>\n      <p><strong>Symptômes usuels</strong> (les plus fréquents) :</p>\n      <ul>\n        <li><span class=\"kw-clinique\">Palpitations</span></li>\n        <li><span class=\"kw-clinique\">Dyspnée d'effort</span> (insuffisance ventriculaire gauche)</li>\n        <li><span class=\"kw-clinique\">Asthénie</span></li>\n        <li><span class=\"kw-clinique\">Angor fonctionnel</span></li>\n      </ul>\n      <p><strong>Autres symptômes</strong>, moins fréquents :</p>\n      <ul>\n        <li>Impression que le cœur « bat trop lentement »</li>\n        <li><span class=\"kw-clinique\">Fatigabilité</span> et mauvaise tolérance à l'effort</li>\n        <li><span class=\"kw-clinique\">Malaise</span>, bouffées de chaleur, <span class=\"kw-clinique\">syncope</span></li>\n        <li><span class=\"kw-clinique\">Œdèmes des membres inférieurs</span> et <span class=\"kw-clinique\">hépatalgies</span> (insuffisance ventriculaire droite)</li>\n        <li><span class=\"kw-clinique\">Chute</span> chez le sujet âgé</li>\n      </ul>\n      <p class=\"obj-renvois\"><em>📎 Items liés : 237 — <span class=\"kw-clinique\">Palpitations</span></em></p>","frequence":1},{"id":"232-5","rang":"A","rubrique":"Diagnostic Positif","titre":"Identifier sur l’électrocardiogramme","contenu":"<p>L'<span class=\"kw-imagerie\">ECG</span> pose le <strong><span class=\"kw-def\">diagnostic positif</span></strong> de FA. Trois éléments le caractérisent.</p>\n      <table >\n        <thead><tr><th>Critère</th><th>Aspect <span class=\"kw-imagerie\">ECG</span></th></tr></thead>\n        <tbody>\n          <tr>\n            <td><strong>Activité atriale</strong></td>\n            <td>\n              <span class=\"kw-radio\">Absence d'onde P</span><br>\n              Remplacée par une <strong><span class=\"kw-radio\">trémulation polymorphe</span></strong> de la ligne de base, d'amplitude ample ou fine (<span class=\"kw-radio\">grosses mailles</span> ou <span class=\"kw-radio\">petites mailles</span>)<br>\n              Fréquence atriale d'environ <span class=\"kw-chiffre\">440/min</span>\n            </td>\n          </tr>\n          <tr>\n            <td><strong>Activité ventriculaire</strong></td>\n            <td>\n              <strong><span class=\"kw-clinique\">Tachycardie</span> irrégulière à QRS fins</strong>, entre <span class=\"kw-chiffre\">100 et 200 bpm</span> (le plus souvent <span class=\"kw-chiffre\">130-180 bpm</span>) au repos, qui s'accélère à l'effort<br>\n              C'est quasiment la <strong>seule cause</strong> de tachycardie irrégulière à QRS fins\n            </td>\n          </tr>\n        </tbody>\n      </table>\n      <p><strong>Situations difficiles</strong> à reconnaître :</p>\n      <ul>\n        <li>FA à <span class=\"kw-radio\">grosses mailles</span> : ne pas la confondre avec un <span class=\"kw-def\">flutter atrial</span> (activité atriale régulière).</li>\n        <li>Association à un <span class=\"kw-def\">bloc de branche</span> (organique ou fonctionnel) : QRS larges.</li>\n        <li>Association à un <span class=\"kw-alerte\">BAV complet (3ᵉ degré)</span> : évoquer la FA si l'activité ventriculaire devient <strong>lente et régulière</strong>.</li>\n        <li>Association à une <span class=\"kw-def\">dysfonction sinusale</span> : alternance <span class=\"kw-clinique\">bradycardie</span> / tachycardie.</li>\n      </ul>\n      <div class=\"callout callout-warn\"><strong>Piège classique.</strong> Une FA dont les QRS deviennent <span class=\"kw-alerte\">lents et réguliers</span> doit faire évoquer un <strong><span class=\"kw-alerte\">BAV complet</span></strong> associé — la régularisation n'est pas un retour en rythme sinusal.</div>\n      <p class=\"obj-renvois\"><em>📎 Items liés : 231 — <span class=\"kw-imagerie\">ECG</span> · 236 — Trouble de conduction intracardiaque</em></p>","frequence":3},{"id":"232-6","rang":"B","rubrique":"Diagnostic Positif","titre":"Connaître la présentation clinique","contenu":"<p><strong>Signes physiques</strong> de la FA :</p>\n      <ul>\n        <li><span class=\"kw-clinique\">Pouls d'amplitude variable</span></li>\n        <li><span class=\"kw-clinique\">Rythme irrégulier</span>, plus ou moins rapide à l'auscultation cardiaque</li>\n        <li><span class=\"kw-clinique\">B1 d'intensité variable</span></li>\n      </ul>\n      <p>L'examen évalue toujours <strong>deux dimensions</strong> :</p>\n      <ul>\n        <li><strong>Tolérance</strong> : FC, PA, FR, diurèse, état de conscience.</li>\n        <li><strong>Complications</strong> : <span class=\"kw-ci\">insuffisance cardiaque</span>, embolie systémique.</li>\n      </ul>\n      <p><strong>Circonstances de découverte</strong> :</p>\n      <ul>\n        <li>Sur des <span class=\"kw-clinique\">symptômes</span> (<span class=\"kw-clinique\">palpitations</span>, <span class=\"kw-clinique\">dyspnée</span>, <span class=\"kw-clinique\">asthénie</span>).</li>\n        <li>Sur une <span class=\"kw-alerte\">complication révélatrice</span> : <span class=\"kw-alerte\">AVC</span>, <span class=\"kw-ci\">insuffisance cardiaque</span>.</li>\n        <li>Lors du <strong><span class=\"kw-def\">dépistage</span></strong> par <span class=\"kw-imagerie\">ECG</span>.</li>\n      </ul>\n      <p><strong>Indications de <span class=\"kw-def\">dépistage</span> de la FA</strong> :</p>\n      <ul>\n        <li><span class=\"kw-imagerie\">ECG</span> <strong>de routine</strong> lors d'un contact médical chez le patient d'âge <span class=\"kw-chiffre\">≥ 65 ans</span> ou à risque.</li>\n        <li><span class=\"kw-imagerie\">ECG</span> <strong>organisé</strong> chez le patient d'âge <span class=\"kw-chiffre\">≥ 75 ans</span>, ou <span class=\"kw-chiffre\">≥ 65 ans</span> à risque thrombo-<span class=\"kw-etio\">embolique</span>.</li>\n        <li><span class=\"kw-imagerie\">ECG</span> <strong>systématique</strong> par monitoring prolongé dans le bilan d'une <span class=\"kw-clinique\">embolie cryptogénique</span>.</li>\n      </ul>","frequence":1},{"id":"232-7","rang":"B","rubrique":"Etiologies","titre":"Connaître les formes cliniques usuelles","contenu":"<p>Les formes cliniques usuelles de FA reposent sur une <strong><span class=\"kw-def\">classification</span> temporelle</strong> — elle conditionne directement la stratégie thérapeutique.</p>\n      <table >\n        <thead><tr><th>Forme</th><th>Définition</th></tr></thead>\n        <tbody>\n          <tr>\n            <td><strong>1ᵉʳ épisode</strong></td>\n            <td>Premier épisode de FA, <span class=\"kw-alerte\">non classable</span> : peut évoluer en forme paroxystique, persistante ou permanente.</td>\n          </tr>\n          <tr>\n            <td><strong>Paroxystique</strong></td>\n            <td>Retour en <span class=\"kw-def\">rythme sinusal</span> en <span class=\"kw-chiffre\">moins de 7 jours</span>, soit spontanément, soit après <span class=\"kw-ttt\">cardioversion</span> (médicamenteuse ou <span class=\"kw-alerte\">choc</span> électrique).</td>\n          </tr>\n          <tr>\n            <td><strong>Persistante</strong></td>\n            <td>Retour en <span class=\"kw-def\">rythme sinusal</span> en <span class=\"kw-chiffre\">plus de 7 jours</span>, spontané ou après <span class=\"kw-ttt\">cardioversion</span>. On parle de FA <strong>persistante de longue durée</strong> si elle dure depuis plus de <span class=\"kw-chiffre\">1 an</span> avec maintien d'une volonté de restauration du rythme sinusal.</td>\n          </tr>\n          <tr>\n            <td><strong>Permanente</strong></td>\n            <td>FA en cas d'<span class=\"kw-alerte\">échec de la cardioversion</span>, ou lorsque la <span class=\"kw-ttt\">cardioversion</span> <strong>n'est pas tentée</strong> (choix d'une stratégie de contrôle de la fréquence, sans volonté de restaurer le rythme sinusal).</td>\n          </tr>\n        </tbody>\n      </table>\n      <div class=\"callout callout-info\"><strong>À retenir.</strong> Le caractère paroxystique / persistant / permanent n'est pas figé : une FA évolue souvent d'une forme paroxystique vers persistante puis permanente, au fil du <span class=\"kw-def\">remodelage atrial</span>.</div>","frequence":0},{"id":"232-8","rang":"B","rubrique":"Etiologies","titre":"Connaître les formes cliniques non usuelles","contenu":"<p>À côté de la <span class=\"kw-def\">classification</span> temporelle, plusieurs formes particulières doivent être identifiées car elles modifient la prise en charge.</p>\n      <table >\n        <thead><tr><th>Forme</th><th>Caractéristiques</th></tr></thead>\n        <tbody>\n          <tr>\n            <td><strong>FA valvulaire</strong></td>\n            <td>FA chez un patient porteur d'une <span class=\"kw-alerte\">prothèse valvulaire mécanique</span>, ou avec un <span class=\"kw-alerte\">rétrécissement mitral rhumatismal modéré à sévère</span>. <span class=\"kw-ci\">Contre-indique les AOD</span> : <span class=\"kw-ttt\">anticoagulation</span> par <span class=\"kw-ttt\">AVK</span> obligatoire.</td>\n          </tr>\n          <tr>\n            <td><strong>FA non valvulaire</strong></td>\n            <td>Toutes les autres FA, y compris en présence d'une bioprothèse, d'une insuffisance aortique, d'une insuffisance mitrale ou d'un rétrécissement aortique.</td>\n          </tr>\n          <tr>\n            <td><strong>FA isolée</strong></td>\n            <td>Absence de cardiopathie sous-jacente et de toute <span class=\"kw-def\">comorbidité</span> (pas d'<span class=\"kw-etio\">HTA</span>, pas de diabète…).</td>\n          </tr>\n          <tr>\n            <td><strong>FA silencieuse</strong></td>\n            <td>Découverte fortuitement chez un patient <span class=\"kw-alerte\">asymptomatique</span>.</td>\n          </tr>\n          <tr>\n            <td><strong>FA aiguë</strong></td>\n            <td>FA de cause aiguë (infection pulmonaire, péricardite, <span class=\"kw-alerte\">SCA</span>, post-opératoire…), à opposer aux FA récidivantes.</td>\n          </tr>\n          <tr>\n            <td><strong>Maladie de l'oreillette</strong></td>\n            <td>Syndrome de <span class=\"kw-def\">tachy-bradycardie</span> : coexistence d'une FA paroxystique et d'une <span class=\"kw-def\">dysfonction sinusale</span>.</td>\n          </tr>\n        </tbody>\n      </table>\n      <div class=\"callout callout-info\"><strong>Forme idiopathique.</strong> Diagnostic d'<strong>exclusion</strong>, avec souvent un substratum <span class=\"kw-etio\">génétique</span> : un ATCD de FA chez un apparenté du <strong>1ᵉʳ degré</strong> augmente de <span class=\"kw-chiffre\">40 %</span> la probabilité d'atteinte.</div>\n      <p class=\"obj-renvois\"><em>📎 Items liés : 233 — Valvulopathie</em></p>","frequence":0},{"id":"232-9","rang":"B","rubrique":"Etiologies","titre":"Connaître les comorbidités de la FA","contenu":"<p>Les <strong><span class=\"kw-def\">comorbidités</span></strong> de la FA sont des pathologies chroniques associées — à distinguer des <strong>facteurs déclenchants</strong> aigus et réversibles. On sépare causes cardiaques, causes extracardiaques et facteurs de prédisposition.</p>\n      <table >\n        <thead><tr><th>Catégorie</th><th>Comorbidités</th></tr></thead>\n        <tbody>\n          <tr>\n            <td><strong>Causes cardiaques</strong><br>(fréquence décroissante)</td>\n            <td>\n              <span class=\"kw-etio\">HTA</span> (souvent avec HVG, surtout chez le sujet âgé)<br>\n              <span class=\"kw-etio\">Insuffisance cardiaque</span><br>\n              <span class=\"kw-etio\">Valvulopathies</span> — surtout mitrales (RM et IM ; risque augmenté chez les porteurs de prothèses valvulaires)<br>\n              <span class=\"kw-etio\">Cardiomyopathies</span> : CMD, CMH, CMR<br>\n              <span class=\"kw-etio\">SCA et séquelles d'infarctus</span> ; <span class=\"kw-etio\">péricardite</span><br>\n              Cardiopathies congénitales (surtout <span class=\"kw-etio\">CIA</span>) ; <span class=\"kw-ttt\">chirurgie</span> cardiaque récente\n            </td>\n          </tr>\n          <tr>\n            <td><strong>Causes extracardiaques</strong></td>\n            <td>\n              <strong>Maladies respiratoires :</strong> <span class=\"kw-etio\">SAS</span> ; pneumopathies infectieuses ; EP ; BPCO ; cœur pulmonaire chronique<br>\n              <strong>Endocriniennes :</strong> <span class=\"kw-etio\">hyperthyroïdie</span> ; <span class=\"kw-etio\">phéochromocytome</span><br>\n              <strong>Autres :</strong> <span class=\"kw-etio\">insuffisance rénale sévère</span> ; <span class=\"kw-etio\">hypovolémie</span>\n            </td>\n          </tr>\n          <tr>\n            <td><strong>Facteurs de prédisposition</strong></td>\n            <td>\n              <span class=\"kw-etio\">Âge</span> — facteur prédisposant le plus puissant<br>\n              <span class=\"kw-etio\">Obésité</span> ; <span class=\"kw-etio\">syndrome d'apnées du sommeil obstructif</span><br>\n              <span class=\"kw-etio\">Hyperthyroïdie</span> ; <span class=\"kw-etio\">diabète</span><br>\n              <span class=\"kw-etio\">Tabac</span> ; consommation excessive d'alcool ; sports de grande endurance (marathon)\n            </td>\n          </tr>\n        </tbody>\n      </table>\n      <div class=\"callout callout-warn\"><strong>À retenir.</strong> Deux dosages sont <strong>systématiques</strong> devant toute FA car ils dépistent des <span class=\"kw-def\">comorbidités</span> traitables : la <span class=\"kw-bio\">TSH</span> (hyperthyroïdie) et la <span class=\"kw-bio\">kaliémie</span> (hypokaliémie).</div>\n      <p class=\"obj-renvois\"><em>📎 Items liés : 224 — <span class=\"kw-etio\">HTA</span> · 234 — <span class=\"kw-ci\">Insuffisance cardiaque</span> · 233 — Valvulopathie · 339 — <span class=\"kw-clinique\">Syndrome coronarien</span> aiguë · 242 — Hyperthyroïdie · 235 — Péricardite aiguë</em></p>","frequence":1},{"id":"232-10","rang":"A","rubrique":"Etiologies","titre":"Connaître les facteurs déclenchants","contenu":"<p>Les <strong>facteurs déclenchants</strong> sont des causes <span class=\"kw-def\">aiguës et rapidement réversibles</span> d'une FA. Les identifier est essentiel : leur correction peut suffire et évite une prise en charge lourde.</p>\n      <ul>\n        <li><span class=\"kw-etio\">Hypokaliémie</span> — <strong>dosage de la <span class=\"kw-bio\">kaliémie</span> systématique</strong>.</li>\n        <li><span class=\"kw-etio\">Fièvre</span> : infection, inflammation.</li>\n        <li><span class=\"kw-etio\">Privation de sommeil</span>.</li>\n        <li><span class=\"kw-etio\">Alcool</span> et <span class=\"kw-etio\">drogues</span> (cocaïne, amphétamines).</li>\n        <li><span class=\"kw-etio\">Électrocution</span>.</li>\n        <li><span class=\"kw-etio\">Réaction vagale</span> (à la suite d'une <span class=\"kw-clinique\">bradycardie</span> secondaire à une hypertonie vagale).</li>\n        <li><span class=\"kw-etio\">Caféine</span> ; médicaments (catécholamines, <span class=\"kw-ttt\">corticoïdes</span>, chimiothérapies…).</li>\n      </ul>\n      <div class=\"callout callout-danger\"><strong>Réflexe EDN.</strong> Toujours rechercher un facteur déclenchant ou prédisposant : s'il existe une cause traitable, il faut la <strong>traiter en priorité</strong> — la prise en charge de la FA elle-même est lourde pour le patient.</div>","frequence":1},{"id":"232-11","rang":"A","rubrique":"Examens complémentaires","titre":"Connaître le bilan de première intention","contenu":"<p>Le bilan paraclinique de <span class=\"kw-chiffre\">première intention</span> recherche une <strong>cardiopathie sous-jacente</strong>, des <strong><span class=\"kw-def\">comorbidités</span> traitables</strong> et prépare l'<strong><span class=\"kw-ttt\">anticoagulation</span></strong>.</p>\n      <table >\n        <thead><tr><th>Niveau</th><th>Examens</th></tr></thead>\n        <tbody>\n          <tr>\n            <td><strong>Bilan systématique</strong></td>\n            <td>\n              <strong>Imagerie / fonctionnel :</strong> <span class=\"kw-imagerie\">ECG</span> ; <span class=\"kw-imagerie\">radiographie thoracique</span> ; <span class=\"kw-imagerie\">échocardiographie transthoracique (ETT)</span> — recherche d'une cardiopathie sous-jacente<br>\n              <strong>Biologie :</strong> <span class=\"kw-bio\">NFS</span> ; <span class=\"kw-bio\">ionogramme sanguin</span> (<span class=\"kw-bio\">kaliémie</span> ++) ; <span class=\"kw-bio\">créatininémie</span> ; <span class=\"kw-bio\">bilan hépatique</span><br>\n              <strong><span class=\"kw-def\">Dépistage</span> de <span class=\"kw-def\">comorbidité</span> :</strong> <span class=\"kw-bio\">TSHus</span><br>\n              <strong>Pré-thérapeutique :</strong> <span class=\"kw-bio\">bilan d'hémostase</span> (avant <span class=\"kw-ttt\">anticoagulation</span>)\n            </td>\n          </tr>\n          <tr>\n            <td><strong>Bilan selon le contexte</strong></td>\n            <td>\n              <strong>Documentation du trouble du rythme :</strong> <span class=\"kw-imagerie\">Holter-ECG prolongé (72 h)</span> si FA suspectée mais non documentée (ex. bilan d'<span class=\"kw-alerte\">AVC</span>) ; interrogation du <span class=\"kw-ttt\">pacemaker</span> ou du DAI si le patient en est porteur<br>\n              <strong><span class=\"kw-def\">Comorbidités</span> :</strong> <span class=\"kw-clinique\">automesure tensionnelle</span> ou <span class=\"kw-clinique\">MAPA</span> ; <span class=\"kw-imagerie\">polysomnographie</span> (recherche de SAS)<br>\n              <strong>Cas rare :</strong> <span class=\"kw-clinique\">test d'effort</span> si FA induite par l'effort\n            </td>\n          </tr>\n        </tbody>\n      </table>\n      <div class=\"callout callout-info\"><strong>À retenir.</strong> La <span class=\"kw-bio\">créatininémie</span> et le <span class=\"kw-bio\">bilan d'hémostase</span> ne sont pas accessoires : ils conditionnent le <strong>choix de l'<span class=\"kw-ttt\">anticoagulant</span></strong> (<span class=\"kw-ttt\">AOD</span> <span class=\"kw-ci\">contre-indiqués</span> si <span class=\"kw-ci\">insuffisance rénale</span> sévère).</div>","frequence":1},{"id":"232-12","rang":"A","rubrique":"Identifier une urgence","titre":"Savoir évaluer le risque thromboembolique et hémorragique","contenu":"<p>L'évaluation du risque thrombo-<span class=\"kw-etio\">embolique</span> guide l'<span class=\"kw-ttt\">anticoagulation</span>, pierre angulaire du <span class=\"kw-def\">pronostic</span> de la FA (qui cause <span class=\"kw-alerte\">1/4 des AVC ischémiques</span>).</p>\n      <div class=\"callout callout-danger\"><strong>Règle fondamentale.</strong> <strong>Toute découverte de FA justifie une <span class=\"kw-ttt\">anticoagulation</span> en aigu.</strong> Le <span class=\"kw-def\">score CHA₂DS₂-VA</span> ne sert qu'à décider de l'<span class=\"kw-ttt\">anticoagulation</span> <strong>au long cours</strong>.</div>\n\n      <h4 style=\"margin:14px 0 6px;font-size:14px;\">Risque thrombo-<span class=\"kw-etio\">embolique</span> — <span class=\"kw-def\">score</span> CHA₂DS₂-VA</h4>\n      <table >\n        <thead><tr><th>Item</th><th>Critère</th><th>Points</th></tr></thead>\n        <tbody>\n          <tr><td><strong>C</strong></td><td>Insuffisance <span class=\"kw-etio\">cardiaque</span> ou dysfonction ventriculaire gauche</td><td><span class=\"kw-chiffre\">1</span></td></tr>\n          <tr><td><strong>H</strong></td><td><span class=\"kw-etio\">HTA</span></td><td><span class=\"kw-chiffre\">1</span></td></tr>\n          <tr><td><strong>A₂</strong></td><td>Âge <span class=\"kw-chiffre\">≥ 75 ans</span></td><td><span class=\"kw-chiffre\">2</span></td></tr>\n          <tr><td><strong>D</strong></td><td><span class=\"kw-etio\">Diabète</span></td><td><span class=\"kw-chiffre\">1</span></td></tr>\n          <tr><td><strong>S₂</strong></td><td>ATCD d'<span class=\"kw-alerte\">AVC</span> / <span class=\"kw-alerte\">AIT</span> / embolie systémique</td><td><span class=\"kw-chiffre\">2</span></td></tr>\n          <tr><td><strong>V</strong></td><td>Maladie <span class=\"kw-etio\">vasculaire</span> (coronaropathie, AOMI, <span class=\"kw-clinique\">plaque</span> aortique)</td><td><span class=\"kw-chiffre\">1</span></td></tr>\n          <tr><td><strong>A</strong></td><td>Âge <span class=\"kw-chiffre\">65-74 ans</span></td><td><span class=\"kw-chiffre\">1</span></td></tr>\n        </tbody>\n      </table>\n      <p><strong>Interprétation</strong> pour l'<span class=\"kw-ttt\">anticoagulation</span> au long cours :</p>\n      <ul>\n        <li><span class=\"kw-def\">Score</span> <span class=\"kw-chiffre\">0</span> → <strong>pas d'<span class=\"kw-ttt\">anticoagulation</span></strong> au long cours (même en FA permanente).</li>\n        <li><span class=\"kw-def\">Score</span> <span class=\"kw-chiffre\">1</span> → <strong>zone grise</strong> : <span class=\"kw-ttt\">anticoagulation</span> discutée au cas par cas (selon le risque <span class=\"kw-etio\">hémorragique</span> et des éléments non pris en compte par le score — <span class=\"kw-ci\">insuffisance rénale</span> sévère, SAHOS).</li>\n        <li><span class=\"kw-def\">Score</span> <span class=\"kw-chiffre\">≥ 2</span> → <strong><span class=\"kw-ttt\">anticoagulation</span> au long cours</strong> indiquée.</li>\n      </ul>\n      <div class=\"callout callout-warn\"><strong>Pièges du <span class=\"kw-def\">score</span>.</strong> Si le score est élevé, l'<span class=\"kw-ttt\">anticoagulation</span> est <strong>maintenue à vie</strong>, même si le patient revient en rythme sinusal. La <span class=\"kw-alerte\">FA valvulaire</span> impose une <span class=\"kw-ttt\">anticoagulation</span> d'emblée (risque élevé) <strong>sans calculer le score</strong> : <span class=\"kw-ttt\">AVK</span> dans tous les cas.</div>\n\n      <h4 style=\"margin:14px 0 6px;font-size:14px;\">Risque <span class=\"kw-etio\">hémorragique</span> — <span class=\"kw-def\">score</span> HAS-BLED</h4>\n      <p>Le <span class=\"kw-def\">score HAS-BLED</span> évalue le risque <span class=\"kw-etio\">hémorragique</span>. Son rôle est précis :</p>\n      <ul>\n        <li>Il permet d'<strong>identifier les patients à risque</strong> afin d'<strong>intensifier leur <span class=\"kw-def\">suivi</span></strong>.</li>\n        <li>Il <span class=\"kw-alerte\">n'a pas de place dans la décision</span> de mise en route d'un traitement <span class=\"kw-ttt\">anticoagulant</span>.</li>\n        <li>Un <span class=\"kw-def\">score</span> HAS-BLED élevé n'est <strong>pas une <span class=\"kw-ci\">contre-indication</span></strong> à l'<span class=\"kw-ttt\">anticoagulation</span>.</li>\n      </ul>\n\n      <h4 style=\"margin:14px 0 6px;font-size:14px;\">Anticoagulation : indications et modalités</h4>\n      <table >\n        <thead><tr><th>Situation</th><th>Modalités</th></tr></thead>\n        <tbody>\n          <tr>\n            <td><strong>En aigu</strong> (<span class=\"kw-ttt\">cardioversion</span> envisagée)</td>\n            <td>\n              <strong>À l'instauration :</strong> <span class=\"kw-ttt\">anticoagulation</span> efficace <span class=\"kw-chiffre\">≥ 3 semaines</span> avant la <span class=\"kw-ttt\">cardioversion</span> — sauf si <span class=\"kw-imagerie\">ETO</span> sans <span class=\"kw-etio\">thrombus</span> intra-OG, ou FA datée avec certitude à <span class=\"kw-chiffre\">&lt; 24 h</span><br>\n              <strong>Après <span class=\"kw-ttt\">réduction</span> :</strong> <span class=\"kw-ttt\">anticoagulation</span> pendant <span class=\"kw-chiffre\">≥ 4 semaines</span> après la cardioversion\n            </td>\n          </tr>\n          <tr>\n            <td><strong><span class=\"kw-ttt\">AOD</span></strong> (1ʳᵉ intention)</td>\n            <td><span class=\"kw-ttt\">Dabigatran</span>, <span class=\"kw-ttt\">rivaroxaban</span>, <span class=\"kw-ttt\">apixaban</span> — à privilégier dans les FA <strong>non valvulaires</strong>. <span class=\"kw-ci\">Contre-indiqués si FA valvulaire ou insuffisance rénale chronique (DFG &lt; 15-30 mL/min)</span>.</td>\n          </tr>\n          <tr>\n            <td><strong><span class=\"kw-ttt\">AVK</span></strong></td>\n            <td>\n              Mise en route par <span class=\"kw-ttt\">HNF</span> à dose curative (<span class=\"kw-ci\">pas d'HBPM dans cette indication</span>), <span class=\"kw-bio\">TCA</span> à <span class=\"kw-chiffre\">2-3 fois</span> le témoin<br>\n              Relais par <span class=\"kw-ttt\">AVK</span> (privilégier la <span class=\"kw-ttt\">warfarine</span>), <span class=\"kw-bio\">INR cible 2-3</span> ; <span class=\"kw-bio\">INR</span> cible <span class=\"kw-chiffre\">3-4,5</span> si valve mécanique mitrale ou valve à disque<br>\n              <span class=\"kw-def\">Surveillance</span> de l'<span class=\"kw-bio\">INR</span> : 1×/semaine à l'instauration, puis 1×/mois\n            </td>\n          </tr>\n          <tr>\n            <td><strong>Fermeture de l'auricule gauche</strong></td>\n            <td>Dispositif percutané (cathétérisme trans-septal) : si haut risque thrombo-<span class=\"kw-etio\">embolique</span> (<span class=\"kw-chiffre\">score ≥ 2</span>), FA <strong>non valvulaire</strong>, et <span class=\"kw-ci\">contre-indication formelle et permanente aux anticoagulants oraux</span> (validée en comité pluridisciplinaire).</td>\n          </tr>\n        </tbody>\n      </table>\n      <p class=\"obj-renvois\"><em>📎 Items liés : 340 — <span class=\"kw-alerte\">AVC</span> · 226 — Thrombose veineuse profonde - EP</em></p>","frequence":4},{"id":"232-13","rang":"A","rubrique":"Prise en Charge","titre":"Connaître les principes de correction des facteurs de risque","contenu":"<p>La correction des <span class=\"kw-def\">facteurs de risque</span> est un <strong>pilier de la prise en charge</strong>, au même titre que l'<span class=\"kw-ttt\">anticoagulation</span> et le contrôle du rythme / de la fréquence : elle réduit la récidive et la progression de la FA.</p>\n      <ul>\n        <li><strong><span class=\"kw-etio\">Obésité / surpoids</span></strong> : corriger — encourager une perte de poids de <span class=\"kw-chiffre\">10 %</span> ou un <span class=\"kw-chiffre\">IMC &lt; 27</span> chez l'obèse.</li>\n        <li><strong><span class=\"kw-etio\">Tabac</span></strong> : <span class=\"kw-ttt\">sevrage</span>.</li>\n        <li><strong><span class=\"kw-etio\">Alcool</span></strong> : limitation de la consommation.</li>\n        <li><strong><span class=\"kw-etio\">HTA</span></strong> : <span class=\"kw-def\">dépistage</span> et traitement — objectif <span class=\"kw-bio\">PAS &lt; 130 mmHg</span>.</li>\n        <li><strong>SAS</strong> : <span class=\"kw-def\">dépistage</span> et traitement (le dépistage par questionnaire n'est plus indiqué).</li>\n        <li><strong><span class=\"kw-ttt\">Activité physique</span></strong> : mise en place d'un programme adapté.</li>\n        <li><strong><span class=\"kw-ci\">Insuffisance cardiaque</span></strong> : adapter et optimiser ses traitements.</li>\n      </ul>\n      <div class=\"callout callout-info\"><strong>À retenir.</strong> Ces mesures rejoignent largement la correction des <strong><span class=\"kw-def\">facteurs de risque cardiovasculaire</span></strong> — la FA s'inscrit dans un continuum de prévention CV global.</div>\n      <p class=\"obj-renvois\"><em>📎 Items liés : 224 — <span class=\"kw-etio\">HTA</span> · 253 — Obésité · 222 — FDR cardiovasculaire</em></p>","frequence":0},{"id":"232-14","rang":"B","rubrique":"Prise en Charge","titre":"Connaître les principes de prise en charge de la FA","contenu":"<p>La prise en charge de la FA repose sur <strong>trois axes</strong> à mener de front : l'<span class=\"kw-ttt\">anticoagulation</span> (cf. risque thrombo-<span class=\"kw-etio\">embolique</span>), la <strong>correction des <span class=\"kw-def\">facteurs de risque</span></strong>, et le choix entre <strong>contrôle du rythme</strong> et <strong>contrôle de la fréquence</strong>.</p>\n\n      <h4 style=\"margin:14px 0 6px;font-size:14px;\">Contrôle du rythme <span class=\"kw-bio\">vs</span> contrôle de la fréquence</h4>\n      <table >\n        <thead><tr><th>Stratégie</th><th>Principe et indications</th></tr></thead>\n        <tbody>\n          <tr>\n            <td><strong>Contrôle du rythme</strong></td>\n            <td><span class=\"kw-ttt\">Réduction</span> puis maintien du <span class=\"kw-def\">rythme sinusal</span>. Indiqué dans la <strong>FA paroxystique</strong> et la <strong>FA persistante</strong>.</td>\n          </tr>\n          <tr>\n            <td><strong>Contrôle de la fréquence</strong></td>\n            <td>On accepte la FA, on cherche seulement à ralentir la FC. Indiqué : en attente de la stratégie de contrôle du rythme ; en cas d'échec de celle-ci (FA permanente) ; d'emblée si le contrôle du rythme semble illusoire.</td>\n          </tr>\n        </tbody>\n      </table>\n\n      <h4 style=\"margin:14px 0 6px;font-size:14px;\">Contrôle du rythme — <span class=\"kw-ttt\">cardioversion</span></h4>\n      <p>La <span class=\"kw-ttt\">cardioversion</span> restaure le rythme sinusal. Avant toute cardioversion, il faut <strong>valider une des 3 conditions suivantes</strong> :</p>\n      <ul>\n        <li>Anticoagulation efficace pendant <span class=\"kw-chiffre\">3 semaines</span>.</li>\n        <li>Réalisation d'une <span class=\"kw-imagerie\">ETO</span> montrant l'absence de <span class=\"kw-etio\">thrombus</span>.</li>\n        <li>FA récente, datée à <span class=\"kw-chiffre\">&lt; 24 h</span>.</li>\n      </ul>\n      <p><strong>Moyens</strong> : <span class=\"kw-ttt\">cardioversion</span> <strong>médicamenteuse</strong> par antiarythmiques (<span class=\"kw-ttt\">amiodarone</span> en bolus, <span class=\"kw-ttt\">flécaïnide</span>, <span class=\"kw-ttt\">sotalol</span>) ou cardioversion <strong>électrique</strong> (<span class=\"kw-alerte\">choc</span> électrique externe sous anesthésie générale). Dans tous les cas : <span class=\"kw-ttt\">anticoagulation</span> <span class=\"kw-chiffre\">≥ 4 semaines</span> après la cardioversion, quel que soit le <span class=\"kw-def\">score</span> CHA₂DS₂-VA.</p>\n\n      <h4 style=\"margin:14px 0 6px;font-size:14px;\">Antiarythmiques selon le <span class=\"kw-def\">terrain</span></h4>\n      <table >\n        <thead><tr><th>Terrain</th><th>Antiarythmique privilégié</th></tr></thead>\n        <tbody>\n          <tr><td><strong>Cœur sain</strong></td><td>1. <span class=\"kw-ttt\">Flécaïnide</span> — 2. si échec : <span class=\"kw-ttt\">sotalol</span> ou <span class=\"kw-ttt\">propafénone</span> — 3. si échec : <span class=\"kw-ttt\">amiodarone</span></td></tr>\n          <tr><td><strong><span class=\"kw-ci\">Insuffisance cardiaque</span></strong></td><td><span class=\"kw-ttt\">Amiodarone</span> — les <span class=\"kw-ci\">autres antiarythmiques sont contre-indiqués</span></td></tr>\n          <tr><td><strong>Patient coronarien</strong></td><td>1. <span class=\"kw-ttt\">Sotalol</span> — 2. si échec : <span class=\"kw-ttt\">amiodarone</span></td></tr>\n        </tbody>\n      </table>\n      <table >\n        <thead><tr><th></th><th>Flécaïnide</th><th>Sotalol</th><th>Amiodarone</th></tr></thead>\n        <tbody>\n          <tr><td><strong>Classe (Vaughan-Williams)</strong></td><td><span class=\"kw-chiffre\">Classe I</span></td><td><span class=\"kw-chiffre\">Classe III</span></td><td><span class=\"kw-chiffre\">Classe III</span></td></tr>\n          <tr><td><strong>Effets indésirables</strong></td><td>Troubles de la conduction</td><td>Troubles de la repolarisation (risque pro-arythmique)</td><td><span class=\"kw-clinique\">Dysthyroïdie</span> ; <span class=\"kw-clinique\">PID</span> ; photosensibilisation ; dépôts cornéens ; hépatite cytolytique ; allongement du QT</td></tr>\n          <tr><td><strong><span class=\"kw-def\">Surveillance</span></strong></td><td><span class=\"kw-imagerie\">ECG</span> (largeur des QRS)</td><td><span class=\"kw-imagerie\">ECG</span> (durée du QT)</td><td>Fonction thyroïdienne, <span class=\"kw-imagerie\">radiographie thoracique</span></td></tr>\n          <tr><td><strong><span class=\"kw-ci\">Contre-indications</span></strong></td><td><span class=\"kw-ci\">Insuffisance cardiaque</span> ; <span class=\"kw-ci\">cardiopathie ischémique</span></td><td><span class=\"kw-ci\">Insuffisance cardiaque</span></td><td>—</td></tr>\n        </tbody>\n      </table>\n\n      <h4 style=\"margin:14px 0 6px;font-size:14px;\">Contrôle de la fréquence</h4>\n      <p><strong>Objectif</strong> : FC de réponse ventriculaire <span class=\"kw-chiffre\">&lt; 80 bpm</span> au repos et <span class=\"kw-chiffre\">&lt; 110 bpm</span> à l'effort modeste (marche de <span class=\"kw-chiffre\">5 min</span>). Efficacité contrôlée par un <span class=\"kw-imagerie\">Holter-ECG</span>.</p>\n      <ul>\n        <li><strong>1ʳᵉ intention — frénateurs nodaux :</strong> <span class=\"kw-ttt\">β-bloquants</span> (<span class=\"kw-ci\">CI dans l'insuffisance cardiaque aiguë</span>, non CI dans l'IC chronique) ; <span class=\"kw-ttt\">inhibiteurs calciques bradycardisants</span> — <span class=\"kw-ttt\">vérapamil</span>, diltiazem (<span class=\"kw-ci\">CI dans l'IC aiguë et chronique</span>) ; <span class=\"kw-ttt\">digoxine</span> (<span class=\"kw-ci\">CI si hypokaliémie ou IRC sévère</span>).</li>\n        <li><strong>2ᵉ intention :</strong> ablation du nœud AV par radiofréquence + pose d'un <span class=\"kw-ttt\">stimulateur cardiaque</span> (à ne pas confondre avec l'ablation de FA).</li>\n      </ul>\n\n      <h4 style=\"margin:14px 0 6px;font-size:14px;\">Traitement interventionnel — ablation</h4>\n      <ul>\n        <li><strong>Ablation de la FA</strong> : désormais recommandée en <strong>1ʳᵉ ligne</strong> dans la FA paroxystique (supérieure aux médicaments pour le maintien du rythme sinusal au long terme). Voie endocavitaire percutanée (cathétérisme transseptal, voie veineuse fémorale) ; énergies : <span class=\"kw-ttt\">cryothérapie</span> ou radiofréquence ; cibles : isolation des veines pulmonaires ou ablation du substrat atrial.</li>\n        <li><strong>Ablation du nœud AV</strong> : pose préalable d'un <span class=\"kw-ttt\">pacemaker</span>, puis ablation du NAV créant un BAV artificiel — si épisodes de FA rapide symptomatique malgré un traitement optimal (stratégie de contrôle de la fréquence).</li>\n      </ul>\n\n      <div class=\"callout callout-danger\"><strong><span class=\"kw-alerte\">OAP</span> sur FA rapide.</strong> Chez un patient en <span class=\"kw-alerte\">insuffisance cardiaque</span> qui fait une FA et un <span class=\"kw-alerte\">OAP</span> : <span class=\"kw-ttt\">digoxine</span> ++ pour ralentir. <span class=\"kw-ci\">Ne pas donner de β-bloquant</span> (ni d'<span class=\"kw-ttt\">inhibiteur calcique</span>) en cas d'IC aiguë sévère — à ne pas cocher en QCM.</div>\n      <p class=\"obj-renvois\"><em>📎 Items liés : 234 — <span class=\"kw-ci\">Insuffisance cardiaque</span> · 339 — <span class=\"kw-clinique\">Syndrome coronarien</span> aiguë</em></p>","frequence":7},{"id":"232-15","rang":"B","rubrique":"Identifier une urgence","titre":"Identifier la mauvaise tolérance et connaître les principes de sa prise en charge","contenu":"<p>La <strong>mauvaise tolérance</strong> d'une FA correspond à une <span class=\"kw-alerte\">instabilité hémodynamique</span> — au maximum, un <span class=\"kw-alerte\">choc cardiogénique</span> sur le trouble du rythme.</p>\n      <p><strong>Signes de mauvaise tolérance à rechercher</strong> : <span class=\"kw-clinique\">hypotension</span>, signes de <span class=\"kw-alerte\">choc</span>, altération de la conscience, signes d'<span class=\"kw-ci\">insuffisance cardiaque</span> aiguë (<span class=\"kw-alerte\">OAP</span>), <span class=\"kw-clinique\">angor</span>, FA très rapide ne répondant pas au traitement freinateur.</p>\n      <div class=\"callout callout-danger\"><strong><span class=\"kw-alerte\">Urgence</span> vitale.</strong> Toute instabilité hémodynamique (<span class=\"kw-alerte\">choc cardiogénique</span>) sur un trouble du rythme, quel qu'il soit, impose un <span class=\"kw-alerte\">choc électrique externe en urgence</span>. <span class=\"kw-ci\">Pas de cardioversion médicamenteuse</span> dans cette situation.</div>\n      <p>Le risque qu'un <span class=\"kw-etio\">thrombus</span> de l'auricule gauche embolise après le <span class=\"kw-alerte\">choc</span> est <strong>accepté</strong> : il est moins grave qu'un décès par <span class=\"kw-alerte\">choc cardiogénique</span>. Cette situation est <strong>rare</strong> — elle s'observe quand la FA est très rapide et ne répond pas au traitement freinateur (<span class=\"kw-ttt\">digoxine</span> IV et/ou <span class=\"kw-ttt\">amiodarone</span> IV).</p>\n      <div class=\"callout callout-warn\"><strong>Cas particulier — FA + <span class=\"kw-alerte\">OAP</span> sur <span class=\"kw-ci\">insuffisance cardiaque</span>.</strong> Si la tolérance permet d'éviter le <span class=\"kw-alerte\">choc</span>, on ralentit par <span class=\"kw-ttt\">digoxine</span> ++ (<span class=\"kw-bio\">kaliémie</span> normale). <span class=\"kw-ci\">β-bloquants et inhibiteurs calciques contre-indiqués</span> en cas d'IC aiguë sévère.</div>\n      <p class=\"obj-renvois\"><em>📎 Items liés : 234 — <span class=\"kw-ci\">Insuffisance cardiaque</span></em></p>","frequence":1}],"astuces":[],"strategie":{"urgence":"<p><strong>FA mal tolérée <span class=\"q\">— instabilité hémodynamique</span></strong></p><p><span class=\"kw-ttt\">Choc électrique externe</span> en <span class=\"kw-alerte\">urgence</span> — <span class=\"kw-ci\">pas de cardioversion médicamenteuse</span></p><ul><li><span class=\"kw-alerte\">Choc cardiogénique</span> sur le trouble du rythme, quel qu'il soit</li><li>Situation <span class=\"kw-chiffre\">rare</span> : <span class=\"kw-clinique\">FA très rapide</span> ne répondant pas au traitement freinateur</li></ul><p><strong>Anticoagulation en aigu</strong></p><p><span class=\"kw-alerte\">FA valvulaire</span> → <span class=\"kw-ttt\">AVK</span> d'emblée, sans calcul du <span class=\"kw-def\">score</span></p><ul><li>Toute découverte de <span class=\"kw-def\">FA</span> justifie une <span class=\"kw-ttt\">anticoagulation</span> en aigu</li><li>Le <span class=\"kw-def\">score CHA₂DS₂-VA</span> ne décide que de l'<span class=\"kw-ttt\">anticoagulation</span> <strong>au long cours</strong></li></ul><p><strong><span class=\"kw-ttt\">Cardioversion</span> <span class=\"q\">— fenêtre des délais</span></strong></p><p>Après <span class=\"kw-ttt\">réduction</span> : <span class=\"kw-ttt\">anticoagulation</span> <span class=\"kw-chiffre\">≥ 4 semaines</span>, quel que soit le <span class=\"kw-def\">score</span></p><ul><li>Réalisable si <strong>1 des 3 conditions</strong> : <span class=\"kw-ttt\">anticoagulation</span> efficace <span class=\"kw-chiffre\">≥ 3 semaines</span>, ou <span class=\"kw-imagerie\">ETO</span> sans <span class=\"kw-etio\">thrombus</span>, ou FA datée <span class=\"kw-chiffre\">&lt; 24 h</span></li><li>Au-delà de <span class=\"kw-chiffre\">48 h</span>, un <span class=\"kw-alerte\">thrombus de l'auricule gauche</span> est probable → <span class=\"kw-ci\">pas de cardioversion</span> sans <span class=\"kw-ttt\">anticoagulation</span> préalable</li></ul>","redflags":"<ul><li><span class=\"kw-alerte\">Hypotension</span> / <span class=\"kw-alerte\">signes de choc</span> (instabilité hémodynamique)</li><li><span class=\"kw-alerte\">Altération de la conscience</span></li><li><span class=\"kw-alerte\">OAP</span> / <span class=\"kw-clinique\">insuffisance cardiaque aiguë</span></li><li><span class=\"kw-clinique\">Angor</span> fonctionnel mal toléré</li><li><span class=\"kw-clinique\">FA très rapide</span> ne répondant pas au traitement freinateur</li><li><span class=\"kw-imagerie\">ECG</span> : <span class=\"kw-alerte\">QRS devenus lents et réguliers</span> → évoquer un <span class=\"kw-def\">BAV complet</span> associé (≠ retour en rythme sinusal)</li></ul>","principes":"<p>Trois axes menés <strong>de front</strong> : <span class=\"kw-ttt\">anticoagulation</span>, <span class=\"kw-def\">correction des facteurs de risque</span>, et choix entre <strong>contrôle du rythme</strong> et <strong>contrôle de la fréquence</strong>.</p><p><strong>Anticoagulation</strong></p><p><span class=\"kw-ttt\">Fermeture de l'auricule gauche</span> si <span class=\"kw-ci\">contre-indication formelle et permanente</span> aux <span class=\"kw-ttt\">anticoagulants</span> (FA non valvulaire, <span class=\"kw-def\">score</span> <span class=\"kw-chiffre\">≥ 2</span>)</p><ul><li><span class=\"kw-ttt\">AOD</span> (<span class=\"kw-ttt\">dabigatran</span>, <span class=\"kw-ttt\">rivaroxaban</span>, <span class=\"kw-ttt\">apixaban</span>) en <strong>1ʳᵉ intention</strong> dans la FA <strong>non valvulaire</strong></li><li><span class=\"kw-ci\">AOD contre-indiqués si FA valvulaire ou IRC sévère (DFG &lt; 15-30 mL/min)</span> → <span class=\"kw-ttt\">HNF</span> puis relais <span class=\"kw-ttt\">AVK</span> (<span class=\"kw-bio\">INR 2-3</span>)</li><li>Au long cours si <span class=\"kw-def\">CHA₂DS₂-VA</span> <span class=\"kw-chiffre\">≥ 2</span> ; <span class=\"kw-chiffre\">0</span> → pas d'<span class=\"kw-ttt\">anticoagulation</span> ; <span class=\"kw-chiffre\">1</span> → discutée au cas par cas</li></ul><p><strong>Contrôle du rythme <span class=\"q\">— FA paroxystique / persistante</span></strong></p><ul><li><span class=\"kw-ttt\">Cardioversion</span> <span class=\"kw-ttt\">médicamenteuse</span> (<span class=\"kw-ttt\">amiodarone</span>, <span class=\"kw-ttt\">flécaïnide</span>, <span class=\"kw-ttt\">sotalol</span>) ou <span class=\"kw-ttt\">électrique</span> (<span class=\"kw-ttt\">CEE</span> sous AG)</li><li>Antiarythmique selon le <span class=\"kw-def\">terrain</span> : cœur sain → <span class=\"kw-ttt\">flécaïnide</span> ; IC → <span class=\"kw-ttt\">amiodarone</span> ; coronarien → <span class=\"kw-ttt\">sotalol</span></li><li><span class=\"kw-ttt\">Ablation de FA</span> (isolation des veines pulmonaires) désormais en <strong>1ʳᵉ ligne</strong> dans la FA paroxystique</li></ul><p><strong>Contrôle de la fréquence <span class=\"q\">— FA permanente</span></strong></p><ul><li>Objectif : <span class=\"kw-chiffre\">FC &lt; 80 bpm</span> au repos, <span class=\"kw-chiffre\">&lt; 110 bpm</span> à l'effort modeste</li><li>Frénateurs nodaux : <span class=\"kw-ttt\">β-bloquants</span> (<span class=\"kw-ci\">CI en IC aiguë</span>), <span class=\"kw-ttt\">inhibiteurs calciques bradycardisants</span> (<span class=\"kw-ci\">CI en IC</span>), <span class=\"kw-ttt\">digoxine</span> (<span class=\"kw-ci\">CI si hypokaliémie / IRC sévère</span>)</li><li>2ᵉ intention : <span class=\"kw-ttt\">ablation du nœud AV</span> + <span class=\"kw-ttt\">stimulateur cardiaque</span></li></ul><p><strong>Correction des <span class=\"kw-def\">facteurs de risque</span></strong></p><ul><li><span class=\"kw-etio\">Obésité</span> : perte de <span class=\"kw-chiffre\">10 %</span> ou <span class=\"kw-chiffre\">IMC &lt; 27</span> ; <span class=\"kw-etio\">tabac</span> : <span class=\"kw-ttt\">sevrage</span> ; <span class=\"kw-etio\">alcool</span> : limitation</li><li><span class=\"kw-etio\">HTA</span> : objectif <span class=\"kw-bio\">PAS &lt; 130 mmHg</span> ; <span class=\"kw-def\">dépistage</span> et traitement du <span class=\"kw-etio\">SAS</span></li><li>Programme d'<span class=\"kw-ttt\">activité physique</span> adapté ; optimisation des traitements de l'<span class=\"kw-etio\">insuffisance cardiaque</span></li></ul>","suivi":"<p><strong><span class=\"kw-ttt\">Anticoagulants</span> <span class=\"q\">— éducation + <span class=\"kw-def\">surveillance</span></span></strong></p><ul><li><span class=\"kw-ttt\">AVK</span> : <span class=\"kw-bio\">INR</span> 1×/semaine à l'instauration puis 1×/mois ; précautions alimentaires</li><li><span class=\"kw-ttt\">AOD</span> : <span class=\"kw-def\">surveillance</span> de la <span class=\"kw-bio\">fonction rénale</span> <span class=\"kw-chiffre\">≥ 1×/an</span></li><li>Éducation aux <span class=\"kw-alerte\">signes d'alarme hémorragiques</span> ; <span class=\"kw-def\">pronostic</span> bénin mais <span class=\"kw-alerte\">risque cérébral</span></li></ul><p><strong>Antiarythmiques <span class=\"q\">— <span class=\"kw-def\">surveillance</span> selon la molécule</span></strong></p><ul><li><span class=\"kw-ttt\">Flécaïnide</span> → <span class=\"kw-imagerie\">ECG</span> (largeur des QRS)</li><li><span class=\"kw-ttt\">Sotalol</span> → <span class=\"kw-imagerie\">ECG</span> (durée du QT, risque pro-arythmique)</li><li><span class=\"kw-ttt\">Amiodarone</span> → <span class=\"kw-bio\">fonction thyroïdienne</span> + <span class=\"kw-imagerie\">RXT</span> (<span class=\"kw-clinique\">PID</span>)</li></ul><p><strong>Efficacité & risque <span class=\"kw-etio\">hémorragique</span></strong></p><ul><li>Contrôle de la fréquence objectivé par un <span class=\"kw-imagerie\">Holter-ECG</span> de contrôle</li><li><span class=\"kw-def\">Score HAS-BLED</span> : identifier les patients à risque pour <strong>intensifier le <span class=\"kw-def\">suivi</span></strong> — <span class=\"kw-ci\">pas une contre-indication</span> à l'<span class=\"kw-ttt\">anticoagulation</span></li></ul>"},"liensGlobaux":[{"href":"https://www.sfcardio.fr/page/chapitre-13-item-232-fibrillation-atriale","label":"SFC — Chapitre 13 item 232 fibrillation atriale"},{"href":"https://www.e-cardiogram.com/fibrillation-atriale-1-generalites/","label":"Fibrillation atriale 1 generalites"},{"href":"https://www.e-cardiogram.com/fibrillation-atriale-2-ecg/","label":"Fibrillation atriale 2 ecg"}],"arbre":{"rootId":"root","nodes":[{"id":"root","kind":"root","label":"FA confirmée à l'ECG : est-elle mal tolérée (instabilité hémodynamique) ? — Toute découverte de FA → anticoagulation en aigu d'emblée","detail":"<h4>CAT — <span class=\"kw-clinique\">fibrillation</span> atriale (prise en charge en aigu) — Tolérance hémodynamique d'abord, puis contrôle du rythme ou de la fréquence</h4>","branches":[{"to":"t-cee","label":"Oui — instabilité hémodynamique / choc cardiogénique","color":"red"},{"to":"q-strategie","label":"Non — FA bien tolérée","color":"blue"}]},{"id":"t-cee","kind":"terminal","label":"Choc électrique externe en urgence","color":"red","detail":"<h4>Indication</h4><ul><li>Toute <span class=\"kw-alerte\">instabilité hémodynamique</span> (<span class=\"kw-alerte\">choc cardiogénique</span>) sur un trouble du rythme, quel qu'il soit</li></ul><h4>Conduite</h4><ul><li><span class=\"kw-ttt\">Choc électrique externe</span> immédiat — <span class=\"kw-ci\">pas de cardioversion médicamenteuse</span> dans cette situation</li></ul><h4>Si un délai est possible</h4><ul><li>Situation <span class=\"kw-chiffre\">rare</span> : <span class=\"kw-clinique\">FA très rapide</span> ne répondant pas au freinateur (<span class=\"kw-ttt\">digoxine IV</span> et/ou <span class=\"kw-ttt\">amiodarone IV</span>)</li></ul><h4>Risque accepté</h4><ul><li>Embolie d'un <span class=\"kw-alerte\">thrombus de l'auricule gauche</span> après le <span class=\"kw-alerte\">choc</span>, jugée moins grave qu'un décès par <span class=\"kw-alerte\">choc cardiogénique</span></li></ul><h4>Renvoi</h4><ul><li>Item 234 (<span class=\"kw-ci\">insuffisance cardiaque</span>)</li></ul>"},{"id":"q-strategie","kind":"decision","label":"Stratégie de fond : contrôle du rythme ou de la fréquence ? — Anticoagulation en aigu déjà débutée · choix selon la forme et le terrain","branches":[{"to":"q-cardioversion","label":"Contrôle du rythme (FA paroxystique / persistante)","color":"blue"},{"to":"q-ic","label":"Contrôle de la fréquence (FA permanente / contrôle du rythme illusoire)","color":"blue"}]},{"id":"q-cardioversion","kind":"decision","label":"Cardioversion réalisable d'emblée ? — 1 des 3 conditions : anticoagulation ≥ 3 sem · ETO sans thrombus · FA datée de moins de 24 h","branches":[{"to":"t-anticoag-differee","label":"Non — aucune condition remplie","color":"amber"},{"to":"q-aa-terrain","label":"Oui — condition validée","color":"blue"}]},{"id":"t-anticoag-differee","kind":"terminal","label":"Anticoagulation puis cardioversion différée","color":"amber","detail":"<h4>Conduite</h4><ul><li><span class=\"kw-ttt\">Anticoagulation</span> efficace <span class=\"kw-chiffre\">≥ 3 semaines</span>, puis <span class=\"kw-ttt\">cardioversion</span> programmée</li></ul><h4>Alternative</h4><ul><li><span class=\"kw-imagerie\">ETO</span> excluant un <span class=\"kw-alerte\">thrombus intra-OG</span> → <span class=\"kw-ttt\">cardioversion</span> plus précoce</li></ul><h4>Après <span class=\"kw-ttt\">réduction</span></h4><ul><li><span class=\"kw-ttt\">Anticoagulation</span> <span class=\"kw-chiffre\">≥ 4 semaines</span>, quel que soit le <span class=\"kw-def\">score</span> CHA₂DS₂-VA</li></ul>"},{"id":"q-aa-terrain","kind":"decision","label":"Antiarythmique selon le terrain ? — Cardioversion médicamenteuse + maintien du rythme sinusal","branches":[{"to":"t-flecaine","label":"Cœur sain","color":"green"},{"to":"t-amiodarone","label":"Insuffisance cardiaque","color":"amber"},{"to":"t-sotalol","label":"Coronarien","color":"amber"}]},{"id":"t-flecaine","kind":"terminal","label":"Flécaïnide (cœur sain)","color":"green","detail":"<h4>Traitement</h4><ul><li>1. <span class=\"kw-ttt\">flécaïnide</span> ; 2. si échec <span class=\"kw-ttt\">sotalol</span> ou <span class=\"kw-ttt\">propafénone</span> ; 3. si échec <span class=\"kw-ttt\">amiodarone</span></li></ul><h4><span class=\"kw-def\">Surveillance</span></h4><ul><li><span class=\"kw-imagerie\">ECG</span> (largeur des QRS)</li></ul><h4><span class=\"kw-ci\">Contre-indications</span></h4><ul><li><span class=\"kw-ci\">Insuffisance cardiaque</span> ; <span class=\"kw-ci\">cardiopathie ischémique</span></li></ul>"},{"id":"t-amiodarone","kind":"terminal","label":"Amiodarone (insuffisance cardiaque)","color":"amber","detail":"<h4>Traitement</h4><ul><li><span class=\"kw-ttt\">Amiodarone</span> — <span class=\"kw-ci\">les autres antiarythmiques sont contre-indiqués</span> en cas d'<span class=\"kw-ci\">insuffisance cardiaque</span></li></ul><h4><span class=\"kw-def\">Surveillance</span></h4><ul><li><span class=\"kw-bio\">Fonction thyroïdienne</span> ; <span class=\"kw-imagerie\">RXT</span> (<span class=\"kw-clinique\">PID</span>) ; allongement du <span class=\"kw-clinique\">QT</span></li></ul>"},{"id":"t-sotalol","kind":"terminal","label":"Sotalol (coronarien)","color":"amber","detail":"<h4>Traitement</h4><ul><li>1. <span class=\"kw-ttt\">sotalol</span> ; 2. si échec <span class=\"kw-ttt\">amiodarone</span></li></ul><h4><span class=\"kw-def\">Surveillance</span></h4><ul><li><span class=\"kw-imagerie\">ECG</span> (durée du QT — risque pro-arythmique)</li></ul><h4><span class=\"kw-ci\">Contre-indication</span></h4><ul><li><span class=\"kw-ci\">Insuffisance cardiaque</span></li></ul>"},{"id":"q-ic","kind":"decision","label":"Insuffisance cardiaque / OAP associé ? — Le terrain conditionne le frénateur nodal","branches":[{"to":"t-frenateurs","label":"Non — pas d'insuffisance cardiaque aiguë","color":"green"},{"to":"t-ic-digoxine","label":"Oui — OAP sur FA rapide","color":"red"}]},{"id":"t-frenateurs","kind":"terminal","label":"Frénateurs nodaux","color":"green","detail":"<h4>Objectif</h4><ul><li><span class=\"kw-chiffre\">FC &lt; 80 bpm</span> au repos, <span class=\"kw-chiffre\">&lt; 110 bpm</span> à l'effort modeste</li></ul><h4>1ʳᵉ intention</h4><ul><li><span class=\"kw-ttt\">β-bloquants</span> ; <span class=\"kw-ttt\">inhibiteurs calciques bradycardisants</span> (<span class=\"kw-ttt\">vérapamil</span>, diltiazem) ; <span class=\"kw-ttt\">digoxine</span> (<span class=\"kw-ci\">CI si hypokaliémie / IRC sévère</span>)</li></ul><h4>2ᵉ intention</h4><ul><li><span class=\"kw-ttt\">Ablation du nœud AV</span> + <span class=\"kw-ttt\">stimulateur cardiaque</span></li></ul><h4><span class=\"kw-def\">Surveillance</span></h4><ul><li><span class=\"kw-imagerie\">Holter-ECG</span> de contrôle</li></ul>"},{"id":"t-ic-digoxine","kind":"terminal","label":"IC / OAP : digoxine en priorité","color":"red","detail":"<h4>Conduite</h4><ul><li><span class=\"kw-ttt\">Digoxine</span> ++ (IV, si <span class=\"kw-bio\">kaliémie</span> normale) ± <span class=\"kw-ttt\">amiodarone IV</span> pour ralentir</li></ul><h4>À ne pas faire</h4><ul><li><span class=\"kw-ci\">β-bloquants et inhibiteurs calciques bradycardisants contre-indiqués</span> en <span class=\"kw-ci\">insuffisance cardiaque</span> aiguë sévère — à ne pas cocher en QCM</li></ul><h4>Renvoi</h4><ul><li>Item 234 (<span class=\"kw-ci\">insuffisance cardiaque</span>)</li></ul>"}]},"cards":[{"i":"8b225d971324","n":232,"o":"232-1","u":"Définition","t":"Connaître la définition de la fibrillation atriale (FA)","q":"Le diagnostic de fibrillation atriale peut-il être posé par photopléthysmographie (montres connectées) ?","a":"<p>Non, le diagnostic de fibrillation atriale par photopléthysmographie (montres connectées) <strong>reste non valide</strong> et impose une <strong>confirmation par électrocardiogramme (ECG)</strong>.</p>"},{"i":"8e90c3d4793f","n":232,"o":"232-1","u":"Définition","t":"Connaître la définition de la fibrillation atriale (FA)","q":"Comment différencier la fibrillation atriale d'un flutter atrial à l'ECG ?","a":"<p>La fibrillation atriale (même à grosses mailles) se distingue du flutter atrial par la <strong>totale irrégularité</strong> de l'activité atriale. Le flutter atrial, quant à lui, présente une <strong>activité atriale régulière en \"dents de scie\"</strong>.</p>"},{"i":"ea16ccfd426b","n":232,"o":"232-1","u":"Définition","t":"Connaître la définition de la fibrillation atriale (FA)","q":"Quelle est la définition de la fibrillation atriale ?","a":"<p>La fibrillation atriale (FA) est un <strong>trouble du rythme supraventriculaire</strong> caractérisé par une <strong>activité électrique auriculaire rapide</strong> (<strong>400 à 600/min</strong>) et <strong>irrégulière</strong>. C'est le trouble du rythme le plus fréquent.</p>"},{"i":"f3e1fea8d4ed","n":232,"o":"232-1","u":"Définition","t":"Connaître la définition de la fibrillation atriale (FA)","q":"Quelles sont les caractéristiques de l'ECG en cas de fibrillation atriale ?","a":"<p>À l'électrocardiogramme (ECG), la fibrillation atriale se caractérise par une <strong>activité atriale totalement irrégulière</strong>, sans onde P bien identifiée. Il n'y a plus de durée minimale d'enregistrement de 30 secondes requise pour le diagnostic.</p>"},{"i":"8c998b2f8fb0","n":232,"o":"232-10","u":"Etiologies","t":"Connaître les facteurs déclenchants","q":"Quels sont les facteurs déclenchants classiques de la fibrillation atriale (FA) qui sont des causes aiguës et réversibles ?","a":"<p>Ces facteurs incluent :</p><ul><li>Une <strong>hypokaliémie</strong>.</li><li>La <strong>fièvre</strong> (liée à une infection ou une inflammation).</li><li>La <strong>privation de sommeil</strong>.</li><li>La consommation d'<strong>alcool</strong> et de <strong>drogues</strong> (cocaïne, amphétamines).</li><li>L'<strong>électrocution</strong>.</li><li>Une <strong>réaction vagale</strong>.</li><li>La consommation de <strong>caféine</strong>.</li><li>Certains <strong>médicaments</strong> (catécholamines, corticoïdes, chimiothérapies).</li></ul>"},{"i":"9a7e63135513","n":232,"o":"232-10","u":"Etiologies","t":"Connaître les facteurs déclenchants","q":"Pourquoi est-il crucial d'identifier les facteurs déclenchants de la fibrillation atriale (FA) ?","a":"<p>Il est crucial d'identifier ces facteurs car leur <strong>correction ou traitement</strong> peut suffire à restaurer un rythme sinusal et éviter une prise en charge plus lourde de la FA elle-même.</p>"},{"i":"de32d8965fcf","n":232,"o":"232-10","u":"Etiologies","t":"Connaître les facteurs déclenchants","q":"Quel examen bilan biologique est systématiquement recommandé pour identifier un facteur déclenchant de la fibrillation atriale (FA) ?","a":"<p>Le <strong>dosage de la kaliémie</strong> est systématiquement recommandé pour rechercher une hypokaliémie, facteur déclenchant fréquent de la FA.</p>"},{"i":"195b647aac2a","n":232,"o":"232-11","u":"Examens complémentaires","t":"Connaître le bilan de première intention","q":"Pourquoi est-il important d'évaluer la créatininémie et de réaliser un bilan d'hémostase avant d'initier une anticoagulation pour une fibrillation atriale ?","a":"<p>Ces examens sont cruciaux car ils <strong>conditionnent le choix de l'anticoagulant</strong>. Les <strong>Anticoagulants Oraux Directs (AOD)</strong> sont par exemple contre-indiqués en cas d'insuffisance rénale sévère.</p>"},{"i":"6e40e43aef71","n":232,"o":"232-11","u":"Examens complémentaires","t":"Connaître le bilan de première intention","q":"Quel est l'objectif principal du bilan paraclinique de première intention face à une fibrillation atriale ?","a":"<p>L'objectif principal est de rechercher une <strong>cardiopathie sous-jacente</strong>, des <strong>comorbidités traitables</strong> et de préparer l'<strong>anticoagulation</strong>.</p>"},{"i":"736cbd3a80b4","n":232,"o":"232-11","u":"Examens complémentaires","t":"Connaître le bilan de première intention","q":"Quels sont les examens d'imagerie et fonctionnels systématiques à réaliser dans le bilan de première intention d'une fibrillation atriale ?","a":"<ul><li><strong>Électrocardiogramme (ECG)</strong>.</li><li><strong>Radiographie thoracique</strong>.</li><li><strong>Échocardiographie transthoracique (ETT)</strong>, qui a pour but de rechercher une cardiopathie sous-jacente.</li></ul>"},{"i":"b39a5a988425","n":232,"o":"232-11","u":"Examens complémentaires","t":"Connaître le bilan de première intention","q":"Quels sont les examens biologiques systématiques à réaliser dans le bilan de première intention d'une fibrillation atriale ?","a":"<ul><li><strong>Numération Formule Sanguine (NFS)</strong>.</li><li><strong>Ionogramme sanguin</strong>, avec une attention particulière à la <strong>kaliémie</strong>.</li><li><strong>Créatininémie</strong>.</li><li><strong>Bilan hépatique</strong>.</li><li><strong>TSHus</strong> pour le dépistage de comorbidités.</li><li><strong>Bilan d'hémostase</strong> à visée pré-thérapeutique, avant anticoagulation.</li></ul>"},{"i":"22e7abfc7d41","n":232,"o":"232-12","u":"Identifier une urgence","t":"Savoir évaluer le risque thromboembolique et hémorragique","q":"Quels sont les critères et les points associés du score CHA₂DS₂-VA pour l'évaluation du risque thromboembolique en cas de fibrillation atriale (FA) ?","a":"<ul><li><strong>C</strong> : Insuffisance cardiaque ou dysfonction ventriculaire gauche (<strong>1 point</strong>)</li><li><strong>H</strong> : HTA (<strong>1 point</strong>)</li><li><strong>A₂</strong> : Âge ≥ 75 ans (<strong>2 points</strong>)</li><li><strong>D</strong> : Diabète (<strong>1 point</strong>)</li><li><strong>S₂</strong> : ATCD d'AVC/AIT/embolie systémique (<strong>2 points</strong>)</li><li><strong>V</strong> : Maladie vasculaire (coronaropathie, AOMI, plaque aortique) (<strong>1 point</strong>)</li><li><strong>A</strong> : Âge 65-74 ans (<strong>1 point</strong>)</li></ul>"},{"i":"636d46cf77b2","n":232,"o":"232-12","u":"Identifier une urgence","t":"Savoir évaluer le risque thromboembolique et hémorragique","q":"Quelle est la particularité de l'anticoagulation en cas de fibrillation atriale (FA) valvulaire ?","a":"<p>La FA valvulaire impose une <strong>anticoagulation d'emblée</strong> (risque élevé) sans calculer le score CHA₂DS₂-VA, et ce sont des <strong>AVK dans tous les cas</strong>.</p>"},{"i":"70abbfd9e39d","n":232,"o":"232-12","u":"Identifier une urgence","t":"Savoir évaluer le risque thromboembolique et hémorragique","q":"Comment interpréter le score CHA₂DS₂-VA pour décider de l'anticoagulation au long cours chez un patient avec fibrillation atriale (FA) ?","a":"<ul><li><strong>Score 0</strong> : pas d'anticoagulation au long cours.</li><li><strong>Score 1</strong> : zone grise, anticoagulation discutée au cas par cas.</li><li><strong>Score ≥ 2</strong> : <strong>anticoagulation au long cours indiquée</strong>.</li></ul>"},{"i":"798dbfa83f09","n":232,"o":"232-12","u":"Identifier une urgence","t":"Savoir évaluer le risque thromboembolique et hémorragique","q":"Quel score est utilisé pour évaluer le risque thromboembolique au long cours chez un patient atteint de fibrillation atriale (FA) ?","a":"<p>Le score utilisé est le <strong>CHA₂DS₂-VA</strong>.</p>"},{"i":"baee62b9ffd0","n":232,"o":"232-12","u":"Identifier une urgence","t":"Savoir évaluer le risque thromboembolique et hémorragique","q":"Quel score est utilisé pour évaluer le risque hémorragique chez un patient sous anticoagulation pour une fibrillation atriale (FA), et quel est son rôle ?","a":"<p>Le score utilisé est le <strong>HAS-BLED</strong>. Il permet d'<strong>identifier les patients à risque hémorragique</strong> afin d'intensifier leur suivi. Il ne doit pas être utilisé pour la décision de mise en route d'un traitement anticoagulant, et un score HAS-BLED élevé n'est pas une contre-indication à l'anticoagulation.</p>"},{"i":"ecfd2d2d8fb1","n":232,"o":"232-12","u":"Identifier une urgence","t":"Savoir évaluer le risque thromboembolique et hémorragique","q":"Comment doit être prise en charge la découverte d'une fibrillation atriale (FA) concernant l'anticoagulation en aigu ?","a":"<p>Toute découverte de FA justifie une <strong>anticoagulation en aigu</strong>.</p>"},{"i":"1120d8c998c7","n":232,"o":"232-13","u":"Prise en Charge","t":"Connaître les principes de correction des facteurs de risque","q":"Quelle est l'importance de la correction des facteurs de risque dans la prise en charge de la fibrillation atriale (FA) ?","a":"<p>La correction des facteurs de risque est un <strong>pilier</strong> de la prise en charge de la FA, au même titre que l'anticoagulation et le contrôle du rythme ou de la fréquence. Elle permet de <strong>réduire la récidive</strong> et la <strong>progression de la FA</strong>.</p>"},{"i":"d2c31e11ef95","n":232,"o":"232-13","u":"Prise en Charge","t":"Connaître les principes de correction des facteurs de risque","q":"Quelles sont les cibles spécifiques de correction des facteurs de risque pour un patient obèse atteint de fibrillation atriale ?","a":"<p>Chez le patient obèse ou en surpoids, il faut encourager une <strong>perte de poids de 10 %</strong> ou viser un <strong>IMC inférieur à 27 kg/m²</strong>.</p>"},{"i":"dac3974bba27","n":232,"o":"232-13","u":"Prise en Charge","t":"Connaître les principes de correction des facteurs de risque","q":"Quels sont les facteurs de risque spécifiques à corriger, en dehors du poids et de l'HTA, pour un patient atteint de fibrillation atriale (FA) ?","a":"<ul><li><strong>Tabac</strong> : sevrage.</li><li><strong>Alcool</strong> : limitation de la consommation.</li><li><strong>Syndrome d'Apnées du Sommeil (SAS)</strong> : dépistage et traitement (le dépistage par questionnaire n'est plus indiqué).</li><li><strong>Activité physique</strong> : mise en place d'un programme adapté.</li><li><strong>Insuffisance cardiaque</strong> : optimisation et adaptation des traitements spécifiques.</li></ul>"},{"i":"ea90185e6341","n":232,"o":"232-13","u":"Prise en Charge","t":"Connaître les principes de correction des facteurs de risque","q":"Comment adapter la prise en charge de l'hypertension artérielle (HTA) chez un patient présentant une fibrillation atriale (FA) ?","a":"<p>L'HTA doit être dépistée et traitée, avec un objectif de <strong>Pression Artérielle Systolique (PAS) inférieure à 130 mmHg</strong> pour le patient atteint de FA.</p>"},{"i":"53d70a098cf7","n":232,"o":"232-4","u":"Diagnostic Positif","t":"Connaître les symptômes usuels","q":"La fibrillation atriale est-elle toujours symptomatique au moment du diagnostic ?","a":"<p>Non, la Fibrillation Atriale est souvent <strong>asymptomatique</strong> et découverte fortuitement lors d'un ECG.</p>"},{"i":"871214513cbd","n":232,"o":"232-4","u":"Diagnostic Positif","t":"Connaître les symptômes usuels","q":"Quels sont les autres symptômes, moins fréquents, pouvant être rencontrés dans la fibrillation atriale ?","a":"<ul><li>Impression que le cœur « bat trop lentement »</li><li>Fatigabilité et mauvaise tolérance à l'effort</li><li>Malaise, bouffées de chaleur, <strong>syncope</strong></li><li><strong>Œdèmes des membres inférieurs et hépatalgies</strong> (liés à une insuffisance ventriculaire droite)</li><li>Chute chez le sujet âgé</li></ul>"},{"i":"99b25a5286ec","n":232,"o":"232-4","u":"Diagnostic Positif","t":"Connaître les symptômes usuels","q":"Quels sont les symptômes usuels les plus fréquents de la fibrillation atriale ?","a":"<ul><li><strong>Palpitations</strong></li><li><strong>Dyspnée d'effort</strong> (liée à une insuffisance ventriculaire gauche)</li><li><strong>Asthénie</strong></li><li><strong>Angor fonctionnel</strong></li></ul>"},{"i":"329cb39c01b0","n":232,"o":"232-5","u":"Diagnostic Positif","t":"Identifier sur l’électrocardiogramme","q":"Quel est le critère électrocardiographique essentiel de l'activité atriale pour le diagnostic positif de fibrillation atriale (FA) ?","a":"<p>Le critère essentiel est l'<strong>absence d'onde P</strong>, remplacée par une <strong>trémulation polymorphe</strong> de la ligne de base. Cette trémulation peut être d'amplitude variable (<strong>grosses mailles ou petites mailles</strong>).</p>"},{"i":"5b578b6ae475","n":232,"o":"232-5","u":"Diagnostic Positif","t":"Identifier sur l’électrocardiogramme","q":"Quelle anomalie doit-on suspecter face à une fibrillation atriale (FA) dont les QRS deviennent lents et réguliers ?","a":"<p>Face à une FA dont les QRS deviennent lents et réguliers, il faut suspecter une <strong>association à un bloc auriculo-ventriculaire (BAV) complet</strong> (3ᵉ degré). La régularisation de l'activité ventriculaire n'est alors pas un retour en rythme sinusal.</p>"},{"i":"89c28d4ab401","n":232,"o":"232-5","u":"Diagnostic Positif","t":"Identifier sur l’électrocardiogramme","q":"Comment se caractérise l'activité ventriculaire sur l'ECG en cas de fibrillation atriale (FA) non compliquée ?","a":"<p>L'activité ventriculaire est caractérisée par une <ul><li><strong>Tachycardie irrégulière</strong></li><li>À <strong>QRS fins</strong></li><li>Fréquence cardiaque entre <strong>100 et 200 bpm</strong> au repos (le plus souvent 130-180 bpm), s'accélérant à l'effort.</li></ul>C'est la cause quasiment exclusive de tachycardie irrégulière à QRS fins.</p>"}]};